     1	package com.pousadamareal.domain.rateplans;
     2	
     3	import com.pousadamareal.domain.RatePlan;
     4	import com.pousadamareal.domain.ReservationRequest;
     5	import com.pousadamareal.domain.Room;
     6	import com.pousadamareal.util.PriceCalculator;
     7	
     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	import java.util.Map;
    11	
    12	public class CorporateRatePlan implements RatePlan {
    13	    private static final Map<String, Integer> COMPANY_DISCOUNTS = Map.of(
    14	        "TECNOSUL", 12,
    15	        "AGROVALE", 18,
    16	        "FARMAVIDA", 25
    17	    );
    18	
    19	    @Override
    20	    public String getName() {
    21	        return "CORPORATE";
    22	    }
    23	
    24	    @Override
    25	    public ValidationResult validate(ReservationRequest request, Room room, int nightCount) {
    26	        if (request.companyCode() == null || request.companyCode().isEmpty()) {
    27	            return ValidationResult.invalid("INVALID_REQUEST", "Company code is required for CORPORATE rate plan");
    28	        }
    29	
    30	        if (!COMPANY_DISCOUNTS.containsKey(request.companyCode())) {
    31	            return ValidationResult.invalid("INVALID_REQUEST", "Invalid company code: " + request.companyCode());
    32	        }
    33	
    34	        return ValidationResult.valid();
    35	    }
    36	
    37	    @Override
    38	    public PricingResult calculatePrice(ReservationRequest request, Room room, int nightCount) {
    39	        long subtotalCents = 0;
    40	        LocalDate current = request.checkIn();
    41	
    42	        while (current.isBefore(request.checkOut())) {
    43	            long nightPrice = room.nightlyRate.multiply(BigDecimal.valueOf(100)).longValue();
    44	            if (PriceCalculator.isHighSeason(current)) {
    45	                nightPrice = PriceCalculator.applyHighSeasonMultiplier(nightPrice);
    46	            }
    47	            subtotalCents += nightPrice;
    48	            current = current.plusDays(1);
    49	        }
    50	
    51	        int discountPercentage = COMPANY_DISCOUNTS.get(request.companyCode());
    52	        long discountCents = PriceCalculator.applyDiscount(subtotalCents, BigDecimal.valueOf(discountPercentage));
    53	        long totalCents = subtotalCents - discountCents;
    54	
    55	        return new PricingResult(subtotalCents, discountCents, totalCents);
    56	    }
    57	
    58	    @Override
    59	    public RefundResult calculateRefund(long amountPaidCents) {
    60	        return new RefundResult(amountPaidCents);
    61	    }
    62	}
