     8	import java.math.BigDecimal;
     9	import java.time.DayOfWeek;
    10	import java.time.LocalDate;
    11	import java.time.temporal.ChronoUnit;
    12	import java.util.Map;
    13	
    14	public class WeekendPackageRatePlan implements RatePlan {
    15	    private static final Map<Room.RoomType, Long> PACKAGE_PRICES = Map.of(
    16	        Room.RoomType.STANDARD, 52000L,
    17	        Room.RoomType.DELUXE, 82000L,
    18	        Room.RoomType.SUITE, 120000L
    19	    );
    20	
    21	    @Override
    22	    public String getName() {
    23	        return "WEEKEND_PACKAGE";
    24	    }
    25	
    26	    @Override
    27	    public ValidationResult validate(ReservationRequest request, Room room, int nightCount) {
    28	        if (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY) {
    29	            return ValidationResult.invalid("INVALID_REQUEST", "Weekend package requires Friday check-in");
    30	        }
    31	
    32	        if (request.checkOut().getDayOfWeek() != DayOfWeek.SUNDAY) {
    33	            return ValidationResult.invalid("INVALID_REQUEST", "Weekend package requires Sunday check-out");
    34	        }
    35	
    36	        long nights = ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
    37	        if (nights != 2) {
    38	            return ValidationResult.invalid("INVALID_REQUEST", "Weekend package requires exactly 2 nights");
    39	        }
    40	
    41	        return ValidationResult.valid();
    42	    }
    43	
    44	    @Override
    45	    public PricingResult calculatePrice(ReservationRequest request, Room room, int nightCount) {
    46	        long priceInCents = PACKAGE_PRICES.get(room.type);
    47	        long discountCents = 0;
    48	        long totalCents = priceInCents;
    49	
    50	        return new PricingResult(priceInCents, discountCents, totalCents);
    51	    }
    52	
    53	    @Override
    54	    public RefundResult calculateRefund(long amountPaidCents) {
    55	        return new RefundResult(amountPaidCents / 2);
    56	    }
    57	}
=== src/main/java/com/pousadamareal/util/PriceCalculator.java
     1	package com.pousadamareal.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PriceCalculator {
     9	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
    10	
    11	    public static long round(BigDecimal value) {
    12	        return value.setScale(2, ROUNDING_MODE).multiply(BigDecimal.valueOf(100)).longValue();
    13	    }
    14	
    15	    public static long round(double value) {
    16	        return round(BigDecimal.valueOf(value));
    17	    }
    18	
    19	    public static boolean isHighSeason(LocalDate date) {
    20	        int month = date.getMonthValue();
    21	
    22	        if (month == 7) {
    23	            return true;
    24	        }
    25	
    26	        if (month == 12) {
    27	            return date.getDayOfMonth() >= 15;
    28	        }
    29	
    30	        if (month == 1 || month == 2) {
    31	            return true;
    32	        }
    33	
    34	        return false;
    35	    }
    36	
    37	    public static long applyHighSeasonMultiplier(long priceInCents) {
    38	        return round(BigDecimal.valueOf(priceInCents).divide(BigDecimal.valueOf(100))
    39	            .multiply(BigDecimal.valueOf(1.20)));
    40	    }
    41	
    42	    public static long applyDiscount(long baseCents, BigDecimal discountPercentage) {
    43	        return round(BigDecimal.valueOf(baseCents)
    44	            .divide(BigDecimal.valueOf(100))
    45	            .multiply(discountPercentage)
    46	            .divide(BigDecimal.valueOf(100)));
    47	    }
    48	
    49	    public static long formatToNonDecimal(long cents) {
    50	        return cents;
    51	    }
    52	}

