     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PriceCalculator {
     9	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
    10	
    11	    public static long round(BigDecimal value) {
    12	        return value.setScale(2, ROUNDING_MODE).multiply(BigDecimal.valueOf(100)).longValue();
    13	    }
    14	
    15	    public static long round(double value) {
    16	        return round(BigDecimal.valueOf(value));
    17	    }
    18	
    19	    public static boolean isHighSeason(LocalDate date) {
    20	        int month = date.getMonthValue();
    21	
    22	        if (month == 7) {
    23	            return true;
    24	        }
    25	
    26	        if (month == 12) {
    27	            return date.getDayOfMonth() >= 15;
    28	        }
    29	
    30	        if (month == 1 || month == 2) {
    31	            return true;
    32	        }
    33	
    34	        return false;
    35	    }
    36	
    37	    public static long applyHighSeasonMultiplier(long priceInCents) {
    38	        return round(BigDecimal.valueOf(priceInCents).divide(BigDecimal.valueOf(100))
    39	            .multiply(BigDecimal.valueOf(1.20)));
    40	    }
    41	
    42	    public static long applyDiscount(long baseCents, BigDecimal discountPercentage) {
    43	        return round(BigDecimal.valueOf(baseCents)
    44	            .divide(BigDecimal.valueOf(100))
    45	            .multiply(discountPercentage)
    46	            .divide(BigDecimal.valueOf(100)));
    47	    }
    48	
    49	    public static long formatToNonDecimal(long cents) {
    50	        return cents;
    51	    }
    52	}

