     5	
     6	import java.time.LocalDate;
     7	import java.time.YearMonth;
     8	import java.time.format.DateTimeFormatter;
     9	import java.util.*;
    10	import java.util.stream.Collectors;
    11	
    12	public class ReportService {
    13	    private final DataStore dataStore;
    14	    private static final DateTimeFormatter ISO_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    15	    private static final DateTimeFormatter ISO_MONTH_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM");
    16	
    17	    public ReportService(DataStore dataStore) {
    18	        this.dataStore = dataStore;
    19	    }
    20	
    21	    public String generateOccupancyReport(LocalDate date) {
    22	        StringBuilder csv = new StringBuilder();
    23	        csv.append("room,type,reservation,check_in,check_out\n");
    24	
    25	        List<Room> sortedRooms = dataStore.getAllRooms().stream()
    26	                .sorted(Comparator.comparingInt(r -> r.number))
    27	                .toList();
    28	
    29	        int occupiedCount = 0;
    30	        for (Room room : sortedRooms) {
    31	            Optional<Reservation> occupant = findOccupantOnDate(room.number, date);
    32	            if (occupant.isPresent()) {
    33	                Reservation res = occupant.get();
    34	                csv.append(res.roomNumber).append(",")
    35	                        .append(room.type.name()).append(",")
    36	                        .append(res.id).append(",")
    37	                        .append(res.checkIn.format(ISO_DATE_FORMAT)).append(",")
    38	                        .append(res.checkOut.format(ISO_DATE_FORMAT)).append("\n");
    39	                occupiedCount++;
    40	            }
    41	        }
    42	
    43	        csv.append("total,").append(occupiedCount).append("/").append(sortedRooms.size()).append("\n");
    44	
    45	        return csv.toString();
    46	    }
    47	
    48	    public String generateRevenueReport(YearMonth month) {
    49	        StringBuilder csv = new StringBuilder();
    50	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    51	
    52	        List<Reservation> relevantReservations = dataStore.getAllReservations().stream()
    53	                .filter(r -> YearMonth.from(r.checkIn).equals(month))
    54	                .filter(r -> r.amountPaidCents > 0)
    55	                .sorted(Comparator.comparing((Reservation r) -> r.checkIn)
    56	                        .thenComparingLong(r -> r.id))
    57	                .toList();
    58	
    59	        long totalAmount = 0;
    60	        for (Reservation res : relevantReservations) {
    61	            long netAmount = res.amountPaidCents;
    62	            if (res.refundCents != null) {
    63	                netAmount -= res.refundCents;
    64	            }
    65	
    66	            csv.append(res.id).append(",")
    67	                    .append(res.roomNumber).append(",")
    68	                    .append(res.checkIn.format(ISO_DATE_FORMAT)).append(",")
    69	                    .append(res.checkOut.format(ISO_DATE_FORMAT)).append(",")
    70	                    .append(res.status.name()).append(",")
    71	                    .append(formatCurrency(netAmount)).append("\n");
    72	
    73	            totalAmount += netAmount;
    74	        }
    75	
    76	        csv.append("total,,,,").append(formatCurrency(totalAmount)).append("\n");
    77	
    78	        return csv.toString();
    79	    }
    80	
    81	    private Optional<Reservation> findOccupantOnDate(int roomNumber, LocalDate date) {
    82	        return dataStore.getAllReservations().stream()
    83	                .filter(r -> r.roomNumber == roomNumber)
    84	                .filter(r -> r.status != Reservation.ReservationStatus.CANCELLED)
    85	                .filter(r -> isOccupantOnDate(r, date))
    86	                .findFirst();
    87	    }
    88	
    89	    private boolean isOccupantOnDate(Reservation r, LocalDate date) {
    90	        return !r.checkIn.isAfter(date) && r.checkOut.isAfter(date);
    91	    }
    92	
    93	    private String formatCurrency(long cents) {
    94	        return String.format("%.2f", cents / 100.0);
    95	    }
    96	}
