    10	
    11	public class ReservationService {
    12	    private final DataStore dataStore;
    13	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    14	
    15	    public ReservationService(DataStore dataStore) {
    16	        this.dataStore = dataStore;
    17	    }
    18	
    19	    public Result<Reservation> createReservation(ReservationRequest request) {
    20	        Room room = dataStore.getRoom(request.roomNumber());
    21	        if (room == null) {
    22	            return Result.error("ROOM_NOT_FOUND", "Room not found");
    23	        }
    24	
    25	        if (request.guests() < 1) {
    26	            return Result.error("INVALID_REQUEST", "At least 1 guest is required");
    27	        }
    28	
    29	        if (request.guests() > room.capacity) {
    30	            return Result.error("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
    31	        }
    32	
    33	        if (request.checkOut().isBefore(request.checkIn()) || request.checkOut().isEqual(request.checkIn())) {
    34	            return Result.error("INVALID_REQUEST", "Check-out must be after check-in");
    35	        }
    36	
    37	        if (!RatePlanFactory.isValidPlanName(request.ratePlan())) {
    38	            return Result.error("INVALID_REQUEST", "Invalid rate plan");
    39	        }
    40	
    41	        RatePlan ratePlan = RatePlanFactory.getPlan(request.ratePlan());
    42	        int nightCount = (int) ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
    43	
    44	        RatePlan.ValidationResult validationResult = ratePlan.validate(request, room, nightCount);
    45	        if (!validationResult.isValid()) {
    46	            return Result.error(validationResult.errorCode().orElse("INVALID_REQUEST"),
    47	                    validationResult.message().orElse("Invalid request"));
    48	        }
    49	
    50	        if (isRoomUnavailable(request.roomNumber(), request.checkIn(), request.checkOut())) {
    51	            return Result.error("ROOM_UNAVAILABLE", "Room is not available for the selected dates");
    52	        }
    53	
    54	        RatePlan.PricingResult pricingResult = ratePlan.calculatePrice(request, room, nightCount);
    55	
    56	        Reservation reservation = new Reservation(
    57	                0,
    58	                request.roomNumber(),
    59	                request.guestName(),
    60	                request.guestEmail(),
    61	                request.guestCpf(),
    62	                request.checkIn(),
    63	                request.checkOut(),
    64	                request.guests(),
    65	                request.ratePlan(),
    66	                nightCount,
    67	                pricingResult.subtotalCents(),
    68	                pricingResult.discountCents(),
