   142	        if (reservation.status != Reservation.ReservationStatus.CHECKED_IN) {
   143	            return Result.error("OPERATION_NOT_ALLOWED", "Only checked-in reservations can be checked out");
   144	        }
   145	
   146	        reservation.status = Reservation.ReservationStatus.CHECKED_OUT;
   147	        dataStore.updateReservation(reservationId, reservation);
   148	
   149	        ReservationReceipt receipt = generateReceipt(reservation);
   150	        return Result.ok(receipt);
   151	    }
   152	
   153	    public Result<ReservationReceipt> getReceipt(long reservationId) {
   154	        Reservation reservation = dataStore.getReservation(reservationId);
   155	        if (reservation == null) {
   156	            return Result.error("RESERVATION_NOT_FOUND", "Reservation not found");
   157	        }
   158	
   159	        if (reservation.amountPaidCents == 0) {
   160	            return Result.error("OPERATION_NOT_ALLOWED", "Second receipt is only available for paid reservations");
   161	        }
   162	
   163	        ReservationReceipt receipt = generateReceipt(reservation);
   164	        return Result.ok(receipt);
   165	    }
   166	
   167	    private ReservationReceipt generateReceipt(Reservation reservation) {
   168	        Room room = dataStore.getRoom(reservation.roomNumber);
   169	        String roomType = room.type.name();
   170	        String nightsLabel = reservation.nights == 1 ? "1 diária" : reservation.nights + " diárias";
   171	
   172	        return new ReservationReceipt(
   173	                "Comprovante de reserva",
   174	                reservation.id,
   175	                reservation.guestName,
   176	                reservation.guestCpf,
   177	                reservation.roomNumber,
   178	                roomType,
   179	                reservation.checkIn.format(DATE_FORMAT),
   180	                reservation.checkOut.format(DATE_FORMAT),
   181	                nightsLabel,
   182	                reservation.subtotalCents,
   183	                reservation.discountCents,
   184	                reservation.totalCents
   185	        );
   186	    }
   187	
   188	    private void sendConfirmationEmail(Reservation reservation) {
   189	        ReservationReceipt receipt = generateReceipt(reservation);
   190	        String receiptText = formatReceipt(receipt);
   191	
   192	        String emailBody = "Olá, " + reservation.guestName + "!\n\n" +
   193	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   194	                receiptText +
   195	                "\n\nA entrada é a partir das 14h, e a saída, até as 12h.\n" +
   196	                "Até breve!";
   197	
   198	        dataStore.createMessage("EMAIL", reservation.guestEmail,
   199	                "Reserva confirmada - Pousada Maré Alta", emailBody);
   200	    }
   201	
   202	    private String formatReceipt(ReservationReceipt receipt) {
   203	        StringBuilder sb = new StringBuilder();
   204	        sb.append("Comprovante de reserva nº ").append(receipt.reservationId()).append("\n");
   205	        sb.append("Hóspede: ").append(receipt.guestName()).append(" (CPF ").append(receipt.guestCpf()).append(")\n");
   206	        sb.append("Quarto: ").append(receipt.roomNumber()).append(" (").append(receipt.roomType()).append(")\n");
   207	        sb.append("Entrada: ").append(receipt.checkIn()).append(" | Saída: ").append(receipt.checkOut())
   208	                .append(" | ").append(receipt.nights()).append("\n");
   209	        sb.append("Diárias: ").append(formatCurrency(receipt.subtotal())).append("\n");
   210	
   211	        if (receipt.discount() > 0) {
   212	            sb.append("Desconto: ").append(formatCurrency(receipt.discount())).append("\n");
   213	        }
   214	
   215	        sb.append("Total: ").append(formatCurrency(receipt.total())).append("\n");
   216	
   217	        return sb.toString();
   218	    }
   219	
   220	    private String formatCurrency(long cents) {
   221	        long reais = cents / 100;
   222	        long centavos = cents % 100;
   223	        return String.format("R$ %d.%02d", reais, centavos);
   224	    }
   225	
   226	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   227	        return dataStore.getAllReservations().stream()
   228	                .filter(r -> r.roomNumber == roomNumber)
   229	                .filter(r -> r.status != Reservation.ReservationStatus.CANCELLED)
   230	                .anyMatch(r -> dateRangesOverlap(r.checkIn, r.checkOut, checkIn, checkOut));
   231	    }
   232	
   233	    private boolean dateRangesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   234	        return start1.isBefore(end2) && start2.isBefore(end1);
   235	    }
   236	
   237	    public record Result<T>(boolean success, T data, String errorCode, String errorMessage) {
   238	        public static <T> Result<T> ok(T data) {
   239	            return new Result<>(true, data, null, null);
   240	        }
   241	
   242	        public static <T> Result<T> error(String code, String message) {
   243	            return new Result<>(false, null, code, message);
   244	        }
   245	    }
   246	
   247	    public record ReservationReceipt(
   248	            String title,
   249	            long reservationId,
   250	            String guestName,
   251	            String guestCpf,
   252	            int roomNumber,
   253	            String roomType,
   254	            String checkIn,
   255	            String checkOut,
   256	            String nights,
   257	            long subtotal,
   258	            long discount,
   259	            long total
   260	    ) {}
   261	}
