    24	
    25	    public void createReservation(Context ctx) {
    26	        try {
    27	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
    28	
    29	            int roomNumber = getIntField(body, "roomNumber");
    30	            String guestName = getStringField(body, "guestName");
    31	            String guestEmail = getStringField(body, "guestEmail");
    32	            String guestCpf = getStringField(body, "guestCpf");
    33	            String checkInStr = getStringField(body, "checkIn");
    34	            String checkOutStr = getStringField(body, "checkOut");
    35	            int guests = getIntField(body, "guests");
    36	            String ratePlan = getStringField(body, "ratePlan");
    37	            String companyCode = body.containsKey("companyCode") ? (String) body.get("companyCode") : null;
    38	
    39	            LocalDate checkIn = parseDate(checkInStr);
    40	            LocalDate checkOut = parseDate(checkOutStr);
    41	
    42	            ReservationRequest request = new ReservationRequest(
    43	                    roomNumber, guestName, guestEmail, guestCpf,
    44	                    checkIn, checkOut, guests, ratePlan, companyCode
    45	            );
    46	
    47	            ReservationService.Result<Reservation> result = reservationService.createReservation(request);
    48	
    49	            if (result.success()) {
    50	                ctx.status(201);
    51	                ctx.json(toJson(result.data()));
    52	            } else {
    53	                ctx.status(getStatusCodeForError(result.errorCode()));
    54	                Map<String, String> error = new HashMap<>();
    55	                error.put("error", result.errorCode());
    56	                error.put("message", result.errorMessage());
    57	                ctx.json(error);
    58	            }
    59	        } catch (Exception e) {
    60	            sendBadRequest(ctx, "INVALID_REQUEST", "Invalid request body");
    61	        }
    62	    }
