    64	    public void getReservation(Context ctx) {
    65	        long id = Long.parseLong(ctx.pathParam("id"));
    66	        Reservation reservation = dataStore.getReservation(id);
    67	
    68	        if (reservation == null) {
    69	            ctx.status(404);
    70	            Map<String, String> error = new HashMap<>();
    71	            error.put("error", "RESERVATION_NOT_FOUND");
    72	            error.put("message", "Reservation not found");
