   133	    public void checkOut(Context ctx) {
   134	        long id = Long.parseLong(ctx.pathParam("id"));
   135	        ReservationService.Result<ReservationService.ReservationReceipt> result = reservationService.checkOut(id);
   136	
   137	        if (result.success()) {
   138	            ctx.json(receiptToJson(result.data()));
   139	        } else {
   140	            ctx.status(getStatusCodeForError(result.errorCode()));
   141	            Map<String, String> error = new HashMap<>();
   142	            error.put("error", result.errorCode());
   143	            error.put("message", result.errorMessage());
   144	            ctx.json(error);
