   147	
   148	    public void getReceipt(Context ctx) {
   149	        long id = Long.parseLong(ctx.pathParam("id"));
   150	        ReservationService.Result<ReservationService.ReservationReceipt> result = reservationService.getReceipt(id);
   151	
   152	        if (result.success()) {
   153	            ctx.json(receiptToJson(result.data()));
   154	        } else {
   155	            ctx.status(getStatusCodeForError(result.errorCode()));
   156	            Map<String, String> error = new HashMap<>();
   157	            error.put("error", result.errorCode());
   158	            error.put("message", result.errorMessage());
   159	            ctx.json(error);
   160	        }
   161	    }
   162	
   163	    private Map<String, Object> toJson(Reservation reservation) {
   164	        Map<String, Object> obj = new HashMap<>();
   165	        obj.put("id", reservation.id);
   166	        obj.put("roomNumber", reservation.roomNumber);
   167	        obj.put("guestName", reservation.guestName);
   168	        obj.put("guestEmail", reservation.guestEmail);
   169	        obj.put("guestCpf", reservation.guestCpf);
   170	        obj.put("checkIn", reservation.checkIn.format(ISO_DATE));
   171	        obj.put("checkOut", reservation.checkOut.format(ISO_DATE));
   172	        obj.put("guests", reservation.guests);
   173	        obj.put("ratePlan", reservation.ratePlan);
   174	        obj.put("nights", reservation.nights);
   175	        obj.put("subtotal", reservation.subtotalCents / 100.0);
   176	        obj.put("discount", reservation.discountCents / 100.0);
   177	        obj.put("total", reservation.totalCents / 100.0);
   178	        obj.put("status", reservation.status.name());
   179	        obj.put("amountPaid", reservation.amountPaidCents / 100.0);
   180	        obj.put("refund", reservation.refundCents != null ? reservation.refundCents / 100.0 : null);
   181	        return obj;
   182	    }
   183	
   184	    private Map<String, Object> receiptToJson(ReservationService.ReservationReceipt receipt) {
   185	        Map<String, Object> obj = new HashMap<>();
   186	        obj.put("title", receipt.title());
   187	        obj.put("reservationId", receipt.reservationId());
   188	        obj.put("guestName", receipt.guestName());
   189	        obj.put("guestCpf", receipt.guestCpf());
   190	        obj.put("roomNumber", receipt.roomNumber());
   191	        obj.put("roomType", receipt.roomType());
   192	        obj.put("checkIn", receipt.checkIn());
   193	        obj.put("checkOut", receipt.checkOut());
   194	        obj.put("nights", receipt.nights());
   195	        obj.put("subtotal", receipt.subtotal() / 100.0);
   196	        obj.put("discount", receipt.discount() / 100.0);
   197	        obj.put("total", receipt.total() / 100.0);
   198	        return obj;
   199	    }
   200	
   201	    private int getIntField(Map<String, Object> obj, String field) {
   202	        if (!obj.containsKey(field)) {
   203	            throw new IllegalArgumentException("Missing field: " + field);
   204	        }
   205	        Object value = obj.get(field);
   206	        if (value instanceof Number) {
   207	            return ((Number) value).intValue();
   208	        }
   209	        return Integer.parseInt(value.toString());
   210	    }
   211	
   212	    private String getStringField(Map<String, Object> obj, String field) {
   213	        if (!obj.containsKey(field)) {
   214	            throw new IllegalArgumentException("Missing field: " + field);
   215	        }
   216	        return (String) obj.get(field);
   217	    }
   218	
   219	    private LocalDate parseDate(String dateStr) {
   220	        try {
   221	            return LocalDate.parse(dateStr, ISO_DATE);
   222	        } catch (DateTimeParseException e) {
   223	            throw new IllegalArgumentException("Invalid date format: " + dateStr);
   224	        }
   225	    }
   226	
   227	    private int getStatusCodeForError(String errorCode) {
   228	        return switch (errorCode) {
   229	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
   230	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
   231	            case "CAPACITY_EXCEEDED" -> 422;
   232	            default -> 400;
   233	        };
   234	    }
   235	
   236	    private void sendBadRequest(Context ctx, String code, String message) {
   237	        ctx.status(400);
   238	        Map<String, String> error = new HashMap<>();
   239	        error.put("error", code);
   240	        error.put("message", message);
   241	        ctx.json(error);
   242	    }
   243	}
